-- Wrong readings, and four sentences that should not have shipped.
--
-- Found by an independent verification pass over the committed seeds, not by
-- the checker — which is the point: `check:examples` validates SEGMENTATION,
-- and every one of these segments perfectly.
--
-- 1. Four kanji annotated with the wrong reading, taught with the authority of
--    ruby: 前 as ぜん rather than まえ in all four 〜前に sentences, 店 as てん
--    rather than みせ, 家 as け rather than いえ, ご飯 as ごめし.
--
--    `readingFor` asked the dictionary before it asked the line. The line knows
--    WHICH word this is; the dictionary only knows which words share the
--    spelling, and a single kanji aligns against any reading you give it. The
--    line is asked first now — except where its reading has swallowed a
--    neighbour, which shows up as the dictionary reading being a prefix of it
--    (毎朝早く gave 毎朝 the reading まいあさはや).
--
-- 2. Four sentences reworded.
--
--    明日来ますか。 — 明日来 is three kanji in a row, so the reading could not be
--    cut between them and 来ます came out as くます. 明日は来ますか。 breaks the
--    run with the particle that belongs there anyway.
--
--    音楽を聞きながらご飯を食べます。 — ご飯 split into ご + 飯, and 飯 alone
--    reads めし. 朝ご飯 is held by the dictionary whole.
--
--    忙しかったら、休みます。 — "if I am busy I will rest" contradicts the two
--    sibling examples the same learner meets (忙しいから、休みません and
--    忙しいとき、休みません). Now 忙しかったら、行きません。
--
--    朝に起きます。 sat in the に-DIRECTION topic while being time-に, and 朝に is
--    stilted besides. Now 海に行きます。
--
-- 3. The four から〜まで word-order questions are removed rather than repaired.
--    まで is not in the dictionary and cuts as ま + で, so the chips read
--    海ま / で — the topic handed the learner a fragment of the very pattern it
--    teaches. A question that cannot be right is worse than one that is absent,
--    and the remaining question types for that topic are unaffected.
--
-- Updated in place, not deleted and re-derived: `lesson_misses` cascades on
-- delete and those rows are the questions a reader owes. Safe to re-run.

-- 1. The rewordings.
UPDATE sentences SET text = '明日は来ますか。', reading_kana = 'あした わ きます か。', updated_at = now() WHERE id = 'sent-ex-ka-4';
UPDATE sentences SET text = '音楽を聞きながら朝ご飯を食べます。', reading_kana = 'おんがく お ききながら あさごはん お たべます。', updated_at = now() WHERE id = 'sent-ex-nagara-4';
UPDATE sentences SET text = '忙しかったら、行きません。', reading_kana = 'いそがしかったら、いきません。', updated_at = now() WHERE id = 'sent-ex-tara-3';
UPDATE sentences SET text = '海に行きます。', reading_kana = 'うみ に いきます。', updated_at = now() WHERE id = 'sent-ex-ni-3';

UPDATE sentence_translations SET text = 'Are you coming tomorrow?',                  updated_at = now() WHERE sentence_id = 'sent-ex-ka-4';
UPDATE sentence_translations SET text = 'I eat breakfast while listening to music.', updated_at = now() WHERE sentence_id = 'sent-ex-nagara-4';
UPDATE sentence_translations SET text = 'If I''m busy, I won''t go.',                updated_at = now() WHERE sentence_id = 'sent-ex-tara-3';
UPDATE sentence_translations SET text = 'I go to the sea.',                          updated_at = now() WHERE sentence_id = 'sent-ex-ni-3';

-- 2. Every authored token, regenerated with the corrected reading rule.
DELETE FROM sentence_tokens WHERE sentence_id IN ('sent-ex-desu-1', 'sent-ex-desu-2', 'sent-ex-desu-4', 'sent-ex-dict-1', 'sent-ex-dict-2', 'sent-ex-dict-3', 'sent-ex-dict-4', 'sent-ex-vclass-2', 'sent-ex-vclass-3', 'sent-ex-vclass-4', 'sent-ex-masu-1', 'sent-ex-masu-3', 'sent-ex-masu-4', 'sent-ex-te-1', 'sent-ex-te-2', 'sent-ex-te-3', 'sent-ex-te-4', 'sent-ex-ta-1', 'sent-ex-ta-2', 'sent-ex-ta-3', 'sent-ex-ta-4', 'sent-ex-teiru-1', 'sent-ex-teiru-2', 'sent-ex-teiru-3', 'sent-ex-teiru-4', 'sent-ex-nai-1', 'sent-ex-nai-2', 'sent-ex-nai-3', 'sent-ex-nai-4', 'sent-ex-desu-3', 'sent-ex-vclass-1', 'sent-ex-masu-2', 'sent-ex-wa-1', 'sent-ex-wa-2', 'sent-ex-wa-3', 'sent-ex-wa-4', 'sent-ex-ga-1', 'sent-ex-ga-2', 'sent-ex-ga-3', 'sent-ex-ga-4', 'sent-ex-kudasai-1', 'sent-ex-kudasai-2', 'sent-ex-kudasai-3', 'sent-ex-kudasai-4', 'sent-ex-mashou-1', 'sent-ex-mashou-2', 'sent-ex-mashou-3', 'sent-ex-mashou-4', 'sent-ex-tai-1', 'sent-ex-tai-2', 'sent-ex-tai-3', 'sent-ex-tai-4', 'sent-ex-kara-1', 'sent-ex-kara-2', 'sent-ex-kara-3', 'sent-ex-kara-4', 'sent-ex-ni-1', 'sent-ex-ni-2', 'sent-ex-ni-4', 'sent-ex-wo-1', 'sent-ex-wo-2', 'sent-ex-wo-3', 'sent-ex-wo-4', 'sent-ex-mo-1', 'sent-ex-mo-2', 'sent-ex-mo-3', 'sent-ex-mo-4', 'sent-ex-aru-1', 'sent-ex-aru-2', 'sent-ex-aru-3', 'sent-ex-aru-4', 'sent-ex-ni-3', 'sent-ex-no-1', 'sent-ex-no-2', 'sent-ex-no-3', 'sent-ex-no-4', 'sent-ex-ka-1', 'sent-ex-ka-2', 'sent-ex-ka-3', 'sent-ex-deloc-1', 'sent-ex-deloc-2', 'sent-ex-deloc-3', 'sent-ex-deloc-4', 'sent-ex-demeans-1', 'sent-ex-demeans-2', 'sent-ex-demeans-3', 'sent-ex-demeans-4', 'sent-ex-he-1', 'sent-ex-he-2', 'sent-ex-he-3', 'sent-ex-he-4', 'sent-ex-to-1', 'sent-ex-to-2', 'sent-ex-to-3', 'sent-ex-to-4', 'sent-ex-ya-1', 'sent-ex-ya-2', 'sent-ex-ya-3', 'sent-ex-ya-4', 'sent-ex-gabut-1', 'sent-ex-gabut-2', 'sent-ex-gabut-3', 'sent-ex-gabut-4', 'sent-ex-iadj-1', 'sent-ex-iadj-2', 'sent-ex-iadj-3', 'sent-ex-iadj-4', 'sent-ex-naadj-1', 'sent-ex-naadj-2', 'sent-ex-naadj-3', 'sent-ex-naadj-4', 'sent-ex-ka-4', 'sent-ex-karamade-1', 'sent-ex-karamade-2', 'sent-ex-karamade-3', 'sent-ex-karamade-4', 'sent-ex-yori-1', 'sent-ex-yori-2', 'sent-ex-yori-3', 'sent-ex-yori-4', 'sent-ex-masenka-1', 'sent-ex-masenka-2', 'sent-ex-masenka-3', 'sent-ex-masenka-4', 'sent-ex-naide-1', 'sent-ex-naide-2', 'sent-ex-naide-3', 'sent-ex-naide-4', 'sent-ex-takoto-1', 'sent-ex-takoto-2', 'sent-ex-takoto-3', 'sent-ex-takoto-4', 'sent-ex-nagara-1', 'sent-ex-nagara-2', 'sent-ex-nagara-3', 'sent-ex-maeni-1', 'sent-ex-maeni-2', 'sent-ex-maeni-3', 'sent-ex-maeni-4', 'sent-ex-atode-1', 'sent-ex-atode-2', 'sent-ex-atode-3', 'sent-ex-atode-4', 'sent-ex-toki-1', 'sent-ex-toki-2', 'sent-ex-toki-3', 'sent-ex-toki-4', 'sent-ex-tara-1', 'sent-ex-tara-2', 'sent-ex-tara-4', 'sent-ex-tara-3', 'sent-ex-nagara-4');

-- 2. The word-order chips and their ruby, rebuilt from those tokens.
WITH grouped AS (
  SELECT
    st.sentence_id, st.index, st.surface, st.furigana,
    -- A chip starts at every token the dictionary knows, and at every token
    -- longer than one character. An unlinked SINGLE kana is a fragment —
    -- `glossLine` shreds anything outside the published vocabulary, so です
    -- arrives as the real particle で plus an orphan す — and it belongs to the
    -- chip before it. Dragging で and す separately is a puzzle about the
    -- tokeniser, not about Japanese.
    sum(CASE WHEN st.word_id IS NOT NULL OR length(st.surface) > 1 THEN 1 ELSE 0 END)
      OVER (PARTITION BY st.sentence_id ORDER BY st.index
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS grp
  FROM sentence_tokens st
  JOIN sentences ss ON ss.id = st.sentence_id AND ss.source = 'authored'
  WHERE st.surface !~ '^[。、！？「」]+$'
),
-- Text and ruby are aggregated SEPARATELY and joined back.
--
-- Doing both in one pass meant lateral-joining the furigana array, which
-- multiplies the row per segment — so a two-segment token had its surface
-- concatenated twice and 朝ご飯を食べる came out as
-- ["朝ご飯","朝ご飯","朝ご飯を","食べる","食べる"].
chip_text AS (
  SELECT sentence_id, grp, min(index) AS pos, string_agg(surface, '' ORDER BY index) AS chip
  FROM grouped GROUP BY sentence_id, grp
),
chip_ruby AS (
  SELECT g.sentence_id, g.grp,
         jsonb_agg(
           CASE WHEN e.seg ? 'r' THEN jsonb_set(e.seg, '{r}', to_jsonb(btrim(e.seg->>'r'))) ELSE e.seg END
           ORDER BY g.index, e.ord
         ) AS ruby
  FROM grouped g
  CROSS JOIN LATERAL jsonb_array_elements(g.furigana) WITH ORDINALITY e(seg, ord)
  GROUP BY g.sentence_id, g.grp
),
chips AS (
  SELECT t.sentence_id, t.pos, t.chip, COALESCE(r.ruby, jsonb_build_array(jsonb_build_object('t', t.chip))) AS ruby
  FROM chip_text t
  LEFT JOIN chip_ruby r ON r.sentence_id = t.sentence_id AND r.grp = t.grp
)
UPDATE exercise_prompts p
SET prompt = p.prompt
      || jsonb_build_object(
           'tokens', (SELECT jsonb_agg(c.chip ORDER BY md5(c.chip || c.sentence_id)) FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId'),
           'tokenFurigana', (SELECT jsonb_object_agg(c.chip, c.ruby) FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId')
         ),
    updated_at = now()
WHERE p.id LIKE 'ep-wo-%'
  AND EXISTS (SELECT 1 FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId');

-- 3. Dictation, which now also accepts the sentence spelled in kana.
UPDATE exercise_prompts p
SET answer = jsonb_build_object(
      'primary', s.text,
      'accepted', jsonb_build_array(
        s.text,
        regexp_replace(s.text, '[。、！？]+$', ''),
        regexp_replace(s.text, '[。、！？「」]', '', 'g')
      ) || CASE WHEN k.kana IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(
        k.kana,
        regexp_replace(k.kana, '[。、！？]+$', ''),
        regexp_replace(k.kana, '[。、！？「」]', '', 'g')
      ) END
    ),
    updated_at = now()
FROM sentences s
LEFT JOIN LATERAL (
  SELECT string_agg(COALESCE(e.seg ->> 'r', e.seg ->> 't'), '' ORDER BY st.index, e.ord) AS kana
  FROM sentence_tokens st
  CROSS JOIN LATERAL jsonb_array_elements(st.furigana) WITH ORDINALITY e(seg, ord)
  WHERE st.sentence_id = s.id
) k ON true
WHERE p.id LIKE 'ep-dict-%' AND s.id = p.assets ->> 'sentenceId';

-- 3b. The word-order ANSWER, which still held the sentence as it used to read.
--
-- 062 rebuilt the chips and their ruby but not the answer, so a reworded
-- sentence had chips that could no longer spell it — the question became
-- unanswerable in the other direction.
UPDATE exercise_prompts p
SET answer = jsonb_build_object(
      'primary', regexp_replace(s.text, '[。、！？「」]', '', 'g'),
      'accepted', jsonb_build_array(
        regexp_replace(s.text, '[。、！？「」]', '', 'g'),
        regexp_replace(s.text, '[。、！？]+$', ''),
        s.text
      )
    ),
    prompt = p.prompt || jsonb_build_object('translation', coalesce(tr.text, p.prompt ->> 'translation')),
    updated_at = now()
FROM sentences s
LEFT JOIN sentence_translations tr ON tr.sentence_id = s.id AND tr.lang = 'en'
WHERE p.id LIKE 'ep-wo-%' AND s.id = p.assets ->> 'sentenceId';

-- 4. The から〜まで word-order questions, which cannot be made correct.
DELETE FROM exercise_prompts WHERE id LIKE 'ep-wo-gp-kara-made-%';
